      "scope": "North Sea offshore wind projects",
      "numerical_value": 1,
      "unit": "km",
      "source": "Marine Spatial Planning Directive 2022",
      "related_domains": ["environmental", "spatial"]
    },
    {
      "type": "Technical",
      "requirement": "Substation foundations must comply with ISO 19902 for offshore structures.",
      "scope": "All offshore wind farms in EU waters",
      "numerical_value": null,
      "unit": null,
      "source": "ISO 19902",
      "related_domains": ["technical", "safety"]
    }
  ],
